function t(s) { return LANG === "en" && EN[s] !== undefined ? EN[s] : s; }
function tt(tpl) {
  let s = t(tpl);
  for (let i = 1; i < arguments.length; i++) s = s.replace("{" + (i - 1) + "}", arguments[i]);
  return s;
}

