function applyStaticEn() {
  if (LANG !== "en") return;
  document.title = "Badminton Tools — TSG - Heilbronn";
  STATIC_EN.forEach(([sel, txt]) => {
    const el = document.querySelector(sel);
    if (el) el.textContent = txt;
  });
  STATIC_EN_HTML.forEach(([sel, html]) => {
    const el = document.querySelector(sel);
    if (el) el.innerHTML = html;
  });
  STATIC_EN_ATTR.forEach(([sel, attr, val]) => {
    const el = document.querySelector(sel);
    if (el) el.setAttribute(attr, val);
  });
  document.querySelector("#rkAddForm button[type=submit]").textContent = "+ Player";
  document.querySelectorAll(".pin-box").forEach(box => {
    const h = box.querySelector("h2"), p = box.querySelector("p");
    if (h && h.textContent.includes("Verlauf")) { h.textContent = "🔒 History locked"; p.textContent = "Enter PIN to view the history."; }
    else if (h) { h.textContent = "🔒 Protected area"; p.textContent = "Enter PIN to continue."; }
  });
  const verlaufH2 = document.querySelector("#tab-termine [data-pin-protect] > h2");
  if (verlaufH2) {
    verlaufH2.childNodes[0].textContent = "History ";
    verlaufH2.querySelector(".hint").textContent = "— who changed what";
  }
  const availH2 = document.querySelector("#tab-termine .panel:nth-child(3) h2");
  if (availH2 && availH2.querySelector(".hint"))
    availH2.innerHTML = availH2.innerHTML
      .replace("Verfügbarkeit", "Availability")
      .replace("— Klick auf Zelle: — → ✓ → ✗ · live geteilt mit dem Team", "— tap a cell: — → ✓ → ✗ · shared live with the team")
      .replace(">verbinde…<", ">connecting…<");
}
applyStaticEn();

const langBtn = document.getElementById("langBtn");
langBtn.textContent = LANG === "de" ? "EN" : "DE";
langBtn.addEventListener("click", () => {
  localStorage.setItem(LANG_KEY, LANG === "de" ? "en" : "de");
  location.reload();
});

/* ================= shared: theme, tabs, toast ================= */
const THEME_KEY = "bwbv-ranking-theme";
const TAB_KEY = "bwbv-tools-tab";

function applyTheme(t) {
  document.documentElement.dataset.theme = t;
  localStorage.setItem(THEME_KEY, t);
  const tc = document.querySelector('meta[name="theme-color"]');
  if (tc) tc.content = t === "dark" ? "#0F1512" : "#F3F6F3";
  const f = document.getElementById("distFrame");
  try {
    if (f && f.contentDocument) f.contentDocument.documentElement.dataset.theme = t;
  } catch {}
}
document.getElementById("themeBtn").addEventListener("click", () => {
  applyTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark");
});
const savedTheme = localStorage.getItem(THEME_KEY);
applyTheme(savedTheme || "light");

document.getElementById("distFrame").addEventListener("load", () => {
  applyTheme(document.documentElement.dataset.theme);
});

const TABS = ["teams", "lineup", "termine", "anfahrt", "shop", "tracker"];
function showTab(id) {
  if (!TABS.includes(id)) id = "teams";
  TABS.forEach(t => {
    document.getElementById("tab-" + t).hidden = t !== id;
    document.getElementById("tabbtn-" + t).setAttribute("aria-selected", String(t === id));
  });
  localStorage.setItem(TAB_KEY, id);
  if (location.hash !== "#" + id) history.replaceState(null, "", "#" + id);
  // Leaflet inside iframe misjudges size while hidden — poke it when shown
  if (id === "anfahrt") {
    const f = document.getElementById("distFrame");
    try { f.contentWindow.dispatchEvent(new f.contentWindow.Event("resize")); } catch {}
  }
}
TABS.forEach(t =>
  document.getElementById("tabbtn-" + t).addEventListener("click", () => showTab(t)));
window.addEventListener("hashchange", () => showTab(location.hash.slice(1)));
showTab(location.hash.slice(1) || localStorage.getItem(TAB_KEY) || "teams");

function esc(s) {
  return String(s).replace(/[&<>"']/g, c =>
    ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
}
let toastTimer;
function toast(msg, undo) {
  const el = document.getElementById("toast");
  el.textContent = msg;
  if (undo) {
    const b = document.createElement("button");
    b.textContent = undo.label;
    b.addEventListener("click", () => { undo.action(); el.classList.remove("show"); });
    el.appendChild(b);
  }
  el.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove("show"), undo ? 6000 : 2200);
}

/* ---- PIN-Schutz für Anfahrt, Shop und Verlauf ---- */
const PIN_HASH = "67be10d98e9ab6d770578f47763baa3bec8e6b3ce68f323cafe00a65ffa43f0d";
const PIN_KEY = "pin-unlock-v1";
async function sha256Hex(s) {
  const b = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, "0")).join("");
}
/* PIN protection temporarily disabled — set PIN_DISABLED to false to re-enable */
const PIN_DISABLED = true;
function pinUnlocked() { return PIN_DISABLED || localStorage.getItem(PIN_KEY) === PIN_HASH; }
function applyPinLocks() {
  document.querySelectorAll("[data-pin-protect]").forEach(el =>
    el.classList.toggle("pin-locked", !pinUnlocked()));
}
